using VisualRelay.Core.Logging;
using VisualRelay.Core.Queue;
using VisualRelay.Domain;

namespace VisualRelay.App.ViewModels;

public partial class MainWindowViewModel
{
    /// <summary>
    /// Spawns a detached relauncher process that waits for this process to
    /// exit (preventing bind-conflict on the control port), then restarts
    /// the app the same way it was started. After spawning, shuts down the
    /// current instance so the relauncher can take over.
    /// </summary>
    internal static async Task TriggerRestartAndShutdownAsync(RestartHandoff handoff)
    {
        var pid = Environment.ProcessId;
        var relaunchArgs = BuildRelaunchArgs(pid, handoff.RootPath);
        if (relaunchArgs is null)
        {
            DrainSummaryLog.Write(handoff.RootPath, handoff.DrainId, "relaunch",
                "restart-handoff", "relauncher-unavailable");
            return;
        }

        var appRestartArgs = BuildAppRestartArgs();

        // Rewrite the handoff with both commands so the detached relauncher
        // knows how to restart the app (separate from how the relauncher
        // itself was spawned). Each is a proper argv array — never pre-joined.
        _ = RestartHandoff.Write(
            handoff.RootPath,
            new RelayTaskOutcome(handoff.CommitSha, RelayTaskOutcomeStatus.Committed,
                handoff.CommitSha, handoff.CommitSha, null),
            handoff.DrainId,
            handoff.PendingCount,
            relaunchCommand: relaunchArgs,
            appRestartCommand: appRestartArgs);

        try
        {
            var startInfo = new System.Diagnostics.ProcessStartInfo
            {
                FileName = relaunchArgs[0],
                WorkingDirectory = handoff.RootPath,
                CreateNoWindow = true,
                UseShellExecute = false,
            };
            for (var i = 1; i < relaunchArgs.Length; i++)
                startInfo.ArgumentList.Add(relaunchArgs[i]);
            System.Diagnostics.Process.Start(startInfo);
        }
        catch (Exception ex)
        {
            DrainSummaryLog.Write(handoff.RootPath, handoff.DrainId, "relaunch",
                "restart-handoff", $"relauncher-failed: {ex.Message}");
            return;
        }

        await Task.Delay(200);
        Environment.Exit(0);
    }

    /// <summary>
    /// Returns the argv to spawn the relauncher itself — one element per
    /// token, never a pre-joined command line. Source checkout:
    /// [dotnet, run, --project, &lt;proj&gt;, --, --parent-pid, &lt;pid&gt;, --root-path, &lt;path&gt;].
    /// Published: [&lt;exe&gt;, --parent-pid, &lt;pid&gt;, --root-path, &lt;path&gt;].
    /// </summary>
    private static string[]? BuildRelaunchArgs(int parentPid, string rootPath)
    {
        var scriptDir = Environment.GetEnvironmentVariable("VISUAL_RELAY_SCRIPT_DIR");
        if (!string.IsNullOrWhiteSpace(scriptDir))
        {
            var proj = Path.Combine(scriptDir, "tools", "VisualRelay.Relauncher");
            return [
                "dotnet", "run", "--project", proj,
                "--", "--parent-pid", parentPid.ToString(), "--root-path", rootPath
            ];
        }

        var appPath = Environment.ProcessPath;
        if (!string.IsNullOrWhiteSpace(appPath))
        {
            var appDir = Path.GetDirectoryName(appPath)!;
            var exe = Path.Combine(appDir, "VisualRelay.Relauncher");
            if (OperatingSystem.IsWindows()) exe += ".exe";
            if (File.Exists(exe))
                return [exe, "--parent-pid", parentPid.ToString(), "--root-path", rootPath];
        }

        return null;
    }

    /// <summary>
    /// Returns the argv to restart THE APP — the target the relauncher spawns
    /// after the current instance exits. Source checkout: [dotnet, run,
    /// --project, &lt;app-proj&gt;, --]. Published: [&lt;app-exe&gt;].
    /// One element per token; never pre-joined.
    /// </summary>
    private static string[]? BuildAppRestartArgs()
    {
        var scriptDir = Environment.GetEnvironmentVariable("VISUAL_RELAY_SCRIPT_DIR");
        if (!string.IsNullOrWhiteSpace(scriptDir))
        {
            var appProj = Path.Combine(scriptDir, "src", "VisualRelay.App");
            return ["dotnet", "run", "--project", appProj, "--"];
        }

        // Published install: restart the app binary.
        if (Environment.ProcessPath is { Length: > 0 } appPath)
            return [appPath];

        return null;
    }
}

