using System.Diagnostics;
using VisualRelay.Core.Logging;
using VisualRelay.Core.Queue;

namespace VisualRelay.Relauncher;

/// <summary>
/// Core relaunch logic: reads the handoff, spawns the app using the true
/// <c>AppRestartCommand</c> argv array, polls for sidecar consumption within
/// a bounded virtual-clock window, and writes drain-log events on failure.
/// </summary>
internal static class Relauncher
{
    /// <summary>Maximum time to wait for the new app instance to consume the sidecar.</summary>
    private static readonly TimeSpan ArrivalTimeout = TimeSpan.FromSeconds(30);
    private static readonly TimeSpan PollInterval = TimeSpan.FromMilliseconds(300);

    internal static async Task<int> RunAsync(
        string rootPath,
        TimeProvider? timeProvider = null,
        CancellationToken cancellationToken = default)
    {
        timeProvider ??= TimeProvider.System;

        var handoff = RestartHandoff.Read(rootPath);
        string[] cmd;
        if (handoff?.AppRestartCommand is { Length: > 0 } appCmd)
        {
            cmd = appCmd;
        }
        else if (handoff?.RelaunchCommand is { Length: > 0 } relaunchCmd)
        {
            // Legacy handoff (pre-AppRestartCommand): accept RelaunchCommand
            // as a fallback so old sidecars aren't silently stranded, but
            // only when it does NOT target the relauncher itself.
            if (!relaunchCmd[0].Contains("VisualRelay.Relauncher"))
            {
                cmd = relaunchCmd;
            }
            else
            {
                // RelaunchCommand targets the relauncher — that's the old
                // broken record. Try the environment fallback.
                cmd = BuildFallbackArgs();
            }
        }
        else
        {
            cmd = BuildFallbackArgs();
        }

        var handoffPath = Path.Combine(rootPath, ".relay", "restart-handoff.json");
        var drainId = handoff?.DrainId ?? "unknown";

        // Spawn the app.
        Process child;
        try
        {
            var startInfo = new ProcessStartInfo
            {
                FileName = cmd[0],
                WorkingDirectory = rootPath,
                CreateNoWindow = false,
                UseShellExecute = false,
            };
            for (var i = 1; i < cmd.Length; i++)
                startInfo.ArgumentList.Add(cmd[i]);

            child = Process.Start(startInfo)
                ?? throw new InvalidOperationException($"Process.Start returned null for {cmd[0]}");
        }
        catch (Exception ex)
        {
            DrainSummaryLog.Write(rootPath, drainId, "relaunch",
                "restart-handoff", $"spawn-failed: {ex.Message}");
            return 1;
        }

        // Wait for the new instance to arrive (sidecar consumed or deleted).
        var deadline = timeProvider.GetUtcNow() + ArrivalTimeout;
        var arrived = false;
        while (timeProvider.GetUtcNow() < deadline && !cancellationToken.IsCancellationRequested)
        {
            if (!File.Exists(handoffPath))
            {
                arrived = true;
                break;
            }

            // Check if the child has already exited — if it died before
            // consuming the sidecar, something went wrong.
            if (child.HasExited)
            {
                break;
            }

            await Task.Delay(PollInterval, timeProvider, cancellationToken);
        }

        if (arrived)
        {
            // Ensure child process isn't orphaned; it's already running.
            child.Dispose();
            return 0;
        }

        // Failure path: child may have exited or timed out.
        var detail = child.HasExited
            ? $"child-exited code={child.ExitCode}"
            : $"arrival-timeout after {ArrivalTimeout.TotalSeconds:F0}s";

        DrainSummaryLog.Write(rootPath, drainId, "relaunch",
            "restart-handoff", detail);

        // Leave the sidecar in place for diagnosis.
        child.Dispose();
        return 1;
    }

    private static string[] BuildFallbackArgs()
    {
        var scriptDir = Environment.GetEnvironmentVariable("VISUAL_RELAY_SCRIPT_DIR");
        if (!string.IsNullOrWhiteSpace(scriptDir))
        {
            var appProj = Path.Combine(scriptDir, "src", "VisualRelay.App");
            return ["dotnet", "run", "--project", appProj, "--"];
        }

        throw new InvalidOperationException(
            "No AppRestartCommand in handoff and VISUAL_RELAY_SCRIPT_DIR is not set");
    }
}

