[Fact]
public async Task Relauncher_SpawnsFakeApp_WithCorrectArgv_AndExitsZero()
{
    using var repo = TestRepository.Create();

    // Fake app: a small self-contained .NET binary we compile on the fly.
    // It writes Environment.GetCommandLineArgs()[1..] one-per-line to a
    // marker file and deletes the handoff sidecar.
    var markerPath = Path.Combine(repo.Root, "fake-app-argv.txt");
    var handoffPath = Path.Combine(repo.Root, ".relay", "restart-handoff.json");
    var fakeAppDir = Path.Combine(repo.Root, "fake-app");
    Directory.CreateDirectory(fakeAppDir);

    var csProj = Path.Combine(fakeAppDir, "fake.csproj");
    File.WriteAllText(csProj,
        "<Project Sdk=\"Microsoft.NET.Sdk\"><PropertyGroup>" +
        "<OutputType>Exe</OutputType><TargetFramework>net10.0</TargetFramework>" +
        "<ImplicitUsings>enable</ImplicitUsings>" +
        "</PropertyGroup></Project>");

    var programCs = Path.Combine(fakeAppDir, "Program.cs");
    File.WriteAllText(programCs,
        $"var args = Environment.GetCommandLineArgs();\n" +
        $"File.WriteAllLines({EscapeCs(markerPath)}, args.Skip(1));\n" +
        $"File.Delete({EscapeCs(handoffPath)});\n");

    // Build the fake app.
    var buildPsi = new System.Diagnostics.ProcessStartInfo
    {
        FileName = "dotnet",
        ArgumentList = { "build", csProj, "-c", "Release", "-o",
            Path.Combine(fakeAppDir, "out") },
        RedirectStandardOutput = true,
        RedirectStandardError = true,
        UseShellExecute = false,
    };
    var buildProc = System.Diagnostics.Process.Start(buildPsi)!;
    buildProc.WaitForExit(60000);
    Assert.True(buildProc.ExitCode == 0,
        $"dotnet build failed: {buildProc.StandardError.ReadToEnd()}");

    var fakeAppExe = Path.Combine(fakeAppDir, "out", "fake");
    var appCmd = new[] { "dotnet", fakeAppExe + ".dll",
        "--flag1", "value with spaces", "--flag2" };

    _ = RestartHandoff.Write(
        repo.Root,
        new RelayTaskOutcome("test", RelayTaskOutcomeStatus.Committed, "hash", "sha", null),
        "drain-test",
        pendingCount: 1,
        appRestartCommand: appCmd);

    Assert.True(File.Exists(handoffPath));

    var time = new ManualTimeProvider();
    var task = VisualRelay.Relauncher.Relauncher.RunAsync(repo.Root, timeProvider: time);

    // Advance virtual time so the polling loop runs; the fake app
