    for (var i = 0; i < 50 && !task.IsCompleted; i++)
    {
        time.Advance(TimeSpan.FromMilliseconds(300));
        System.Threading.Thread.Sleep(0);
    }

    var exitCode = await task;
    Assert.Equal(0, exitCode);

    // The fake app writes args[1..] = ["--flag1", "value with spaces", "--flag2"]
    Assert.True(File.Exists(markerPath));
    var lines = File.ReadAllLines(markerPath);
    Assert.Equal(new[] { "--flag1", "value with spaces", "--flag2" }, lines);

    // Sidecar must be consumed.
    Assert.False(File.Exists(handoffPath));
}

/// <summary>Produces a C# verbatim string literal for the given path.</summary>
private static string EscapeCs(string path)
