        {
            "python3", "-c",
            "import sys,os\n" +
            $"open({EscapePy(markerPath)},'w').write('\\n'.join(sys.argv[1:-1]))\n" +
            $"os.remove({EscapePy(handoffPath)})",
            // Remaining args are the user flags + the handoff path (last).
            "--flag1", "value with spaces", "--flag2"
