    }

    /// <summary>Produces a Python raw-string literal for the given path.</summary>
    private static string EscapePy(string path)
    {
        var escaped = path.Replace("\\", "\\\\").Replace("'", "\\'");
        return $"r'{escaped}'";
    }
}

