        var scriptPath = Path.Combine(repo.Root, "fake-app.sh");
        File.WriteAllText(scriptPath,
            $"printf '%s\\n' \"$@\" > {EscapeSh(markerPath)}\n" +
            $"rm -f {EscapeSh(handoffPath)}\n");

